-- Drill library v2: the practice-plan generator's fields (research spec, sections 2-5). Additive: no row or column is dropped.
-- Run in the Supabase SQL editor.

alter table public.drill_library add column if not exists practice_category text
  check (practice_category in ('lag_putting', 'short_putting', 'short_game', 'wedges', 'approach', 'tee', 'warmup', 'closeout'));
alter table public.drill_library add column if not exists locations text[] not null default '{}'
  check (locations <@ array['home_net', 'short_game_area', 'range', 'course', 'simulator', 'putting_green']);
alter table public.drill_library add column if not exists equipment text;
alter table public.drill_library add column if not exists structure text check (structure in ('blocked', 'blocked_serial_random', 'random'));
alter table public.drill_library add column if not exists pressure smallint not null default 0 check (pressure between 0 and 2);  -- 2 = restart rule or stake
alter table public.drill_library add column if not exists metric text check (metric in ('count_of_n', 'streak', 'strokes', 'pct'));
alter table public.drill_library add column if not exists lower_is_better boolean not null default false;
alter table public.drill_library add column if not exists sets jsonb not null default '[]';     -- ordered [{label, setup, balls, club?}]
alter table public.drill_library add column if not exists levels jsonb not null default '[]';   -- ordered [{name, rule}]
alter table public.drill_library add column if not exists cue text;            -- external focus only
alter table public.drill_library add column if not exists routine_rule text;
alter table public.drill_library add column if not exists source_url text;
alter table public.drill_library add column if not exists status text not null default 'active' check (status in ('active', 'closed', 'locked'));

-- Targets now come from levels, not from "Goal: N/M" sentences in the instructions.
update public.drill_library set instructions = trim(regexp_replace(instructions, '\s*Goal:[^.]*\.', '', 'g')) where instructions like '%Goal:%';

-- Existing drills with no score or no basis in the spec stay in the table (user_drills references them) but never appear.
update public.drill_library d set status = 'closed', practice_category = c.practice_category, locations = c.locations
from (values
  ('Tee Shot Consistency', 'tee', array['range']),
  ('Start-Line Gate', 'tee', array['range', 'home_net']),
  ('Club-Down Tee Shots', 'tee', array['range']),
  ('Pressure Driver Ten', 'tee', array['range']),
  ('100 Approach Shots', 'approach', array['range']),
  ('Stock Iron Dispersion', 'approach', array['range']),
  ('Par-3 Tee Shots', 'approach', array['range']),
  ('Wedge Distance Ladder', 'wedges', array['range', 'home_net', 'simulator']),
  ('Greenside Chips', 'short_game', array['short_game_area']),
  ('Bunker Escapes', 'short_game', array['short_game_area']),
  ('Pitch Distance Ladder', 'short_game', array['short_game_area']),
  ('Lag Putting', 'lag_putting', array['putting_green']),
  ('Lag Ladder', 'lag_putting', array['putting_green']),
  ('3-Foot Putts', 'short_putting', array['putting_green']),
  ('Clock Drill', 'short_putting', array['putting_green'])
) as c(name, practice_category, locations)
where d.name = c.name;

-- New drills, and the v2 fields of the four existing drills that match the spec. The test parses this JSON.
insert into public.drill_library (name, category, description, target_area, difficulty, reps_suggested, time_estimate_mins, instructions, equipment_needed, practice_category, locations, equipment, structure, pressure, metric, lower_is_better, sets, levels, cue, routine_rule, source_url, status)
select name, category, description, target_area, difficulty, reps_suggested, time_estimate_mins, instructions, equipment_needed, practice_category, locations, equipment, structure, pressure, metric, lower_is_better, sets, levels, cue, routine_rule, source_url, status
from jsonb_to_recordset($seed$
[
  {"category":"putting","difficulty":"advanced","lower_is_better":true,"status":"active","reps_suggested":15,"equipment_needed":"putter, balls, tees","name":"Mickelson Lag Stations","practice_category":"lag_putting","description":"Three lag distances in a set order, each cleared with a streak.","target_area":"lag","time_estimate_mins":20,"instructions":"Mark stations at 40, 30 and 50 feet. Putt from 40 feet until 5 in a row finish inside the 3-foot circle, then move to 30 feet, then 50 feet. Log the total putts it took to clear all three stations.","locations":["putting_green"],"equipment":"putter, balls, tees","structure":"random","pressure":2,"metric":"strokes","sets":[{"label":"Station 1, 40 ft","setup":"5 in a row inside the 3-ft circle to move on","balls":5},{"label":"Station 2, 30 ft","setup":"5 in a row inside the 3-ft circle to move on","balls":5},{"label":"Station 3, 50 ft","setup":"5 in a row inside the 3-ft circle to finish","balls":5}],"levels":[{"name":"3-ft zone","rule":"5 in a row inside 3 ft at each station"},{"name":"2-ft zone","rule":"5 in a row inside 2 ft at each station"}],"cue":"Roll each ball to stop inside the circle around the hole.","routine_rule":"Full routine on every putt.","source_url":"https://www.golfdigest.com/story/harmon_gd0805"},
  {"category":"putting","difficulty":"intermediate","lower_is_better":true,"status":"active","reps_suggested":40,"equipment_needed":"putter, balls, tees","name":"Pelz Lag Ladder","practice_category":"lag_putting","description":"Ten balls at each of four lag distances, counting the ones that finish outside the zone.","target_area":"lag","time_estimate_mins":25,"instructions":"Putt 10 balls from 20 feet, then 10 from 30, 40 and 50 feet. After each distance, count the balls that finished outside the zone around the hole.","locations":["putting_green"],"equipment":"putter, balls, tees","structure":"blocked","pressure":0,"metric":"count_of_n","sets":[{"label":"20 ft","setup":"10 putts from 20 ft; count the balls outside the zone","balls":10},{"label":"30 ft","setup":"10 putts from 30 ft; count the balls outside the zone","balls":10},{"label":"40 ft","setup":"10 putts from 40 ft; count the balls outside the zone","balls":10},{"label":"50 ft","setup":"10 putts from 50 ft; count the balls outside the zone","balls":10}],"levels":[{"name":"6-ft zone","rule":"2 or fewer of 10 outside 6 ft at each distance"},{"name":"3-ft zone","rule":"5 or fewer of 10 outside 3 ft at each distance"},{"name":"2-ft zone","rule":"7 or fewer of 10 outside 2 ft at each distance"}],"cue":"Roll each ball to stop about 17 inches past the hole.","routine_rule":"Full routine on every putt.","source_url":"https://golf.com/instruction/10-brilliant-short-game-tips-dave-pelz-timeless-tips/"},
  {"category":"putting","difficulty":"beginner","lower_is_better":false,"status":"active","reps_suggested":10,"equipment_needed":"putter, balls, 2 tees","name":"Speed Calibration","practice_category":"warmup","description":"Warm-up that sets your putting speed before a round or session.","target_area":"speed","time_estimate_mins":5,"instructions":"Put a tee at the far edge of the green. Roll 5 balls across the green to it, then 5 back to a tee at the starting edge. Count the balls that stop within the zone around the tee.","locations":["putting_green"],"equipment":"putter, balls, 2 tees","structure":"blocked","pressure":0,"metric":"count_of_n","sets":[{"label":"Across","setup":"5 balls across the green to the far tee","balls":5},{"label":"Back","setup":"5 balls back to the starting tee","balls":5}],"levels":[{"name":"4-ft zone","rule":"6 of 10 stop within 4 ft of the tee"},{"name":"3-ft zone","rule":"6 of 10 stop within 3 ft of the tee"}],"cue":"Roll each ball to stop at the tee.","routine_rule":"One look at the target, then roll.","source_url":"https://golf.com/instruction/putting/sam-burn-putting-drill-fully-equipped/"},
  {"category":"putting","difficulty":"intermediate","lower_is_better":false,"status":"active","reps_suggested":10,"equipment_needed":"putter, balls, 10 tees","name":"3-Foot Circle","practice_category":"short_putting","description":"A ring of 3-footers where a miss sends you back to the start.","target_area":"short putts","time_estimate_mins":15,"instructions":"Place 10 tees in a ring 3 feet from the hole. Putt from each tee in turn. A miss restarts the ring. Log your best streak of makes in a row.","locations":["putting_green"],"equipment":"putter, balls, 10 tees","structure":"blocked","pressure":2,"metric":"streak","sets":[{"label":"Ring","setup":"10 tees 3 ft from the hole; a miss restarts the ring","balls":10}],"levels":[{"name":"3 ft, 5 in a row","rule":"Best streak of 5 from 3 ft"},{"name":"3 ft, 10 in a row","rule":"Best streak of 10 from 3 ft"},{"name":"4 ft, 10 in a row","rule":"Best streak of 10 from 4 ft"}],"cue":"Roll each putt into the back of the cup.","routine_rule":"Full routine on every putt.","source_url":"https://golf.com/instruction/phil-mickelson-key-3-footer-play-smart/"},
  {"category":"putting","difficulty":"intermediate","lower_is_better":false,"status":"active","reps_suggested":20,"equipment_needed":"putter, balls, 2 tees","name":"Putting Gate","practice_category":"short_putting","description":"Roll putts through a narrow gate to the hole.","target_area":"start line","time_estimate_mins":15,"instructions":"Push two tees into the green about 4 feet from the ball, just wider than the putter head. Roll 20 putts through the gate toward the hole. Count the putts that pass cleanly through.","locations":["putting_green"],"equipment":"putter, balls, 2 tees","structure":"blocked","pressure":0,"metric":"count_of_n","sets":[{"label":"Gate","setup":"Gate 4 ft from the ball; count clean passes","balls":20}],"levels":[{"name":"Wide gate","rule":"Tees one ball-width wider than the putter head: 12 of 20 clean"},{"name":"Tight gate","rule":"Tees half a ball-width wider than the putter head: 12 of 20 clean"}],"cue":"Roll the ball along the start line, through the gate, to the cup.","routine_rule":"Full routine on every putt.","source_url":"https://www.golfdigest.com/story/tiger-woods-putting-drill-gate-two-tees"},
  {"category":"putting","difficulty":"intermediate","lower_is_better":false,"status":"active","reps_suggested":10,"equipment_needed":"putter, balls","name":"Quiet-Eye Putts","practice_category":"short_putting","description":"Ten-footers with a steady gaze on the back of the ball.","target_area":"short putts","time_estimate_mins":10,"instructions":"Putt 10 balls from 10 feet. Settle your gaze on the back of the ball, hold it through the stroke and a moment after. Count the makes.","locations":["putting_green"],"equipment":"putter, balls","structure":"blocked","pressure":0,"metric":"count_of_n","sets":[{"label":"10 ft","setup":"10 putts from 10 ft; count the makes","balls":10}],"levels":[{"name":"3 of 10","rule":"Make 3 of 10 from 10 ft"},{"name":"4 of 10","rule":"Make 4 of 10 from 10 ft (the Tour rate there is 41%)"}],"cue":"Fix your gaze on the back of the ball and hold it there until the ball is well on its way.","routine_rule":"Full routine on every putt.","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3111367"},
  {"category":"putting","difficulty":"intermediate","lower_is_better":true,"status":"active","reps_suggested":9,"equipment_needed":"putter, balls","name":"Nine-Hole Putting Course","practice_category":"lag_putting","description":"Hole out every ball on a nine-hole course laid out on the green.","target_area":"putting","time_estimate_mins":20,"instructions":"Pick nine holes 10 to 40 feet apart on the practice green. Play one ball to each hole and hole out everything. Log your total putts.","locations":["putting_green"],"equipment":"putter, balls","structure":"random","pressure":1,"metric":"strokes","sets":[{"label":"Front nine","setup":"One ball per hole, hole out everything","balls":9}],"levels":[{"name":"18 putts","rule":"Finish the nine in 18 putts or fewer"},{"name":"16 putts","rule":"Finish the nine in 16 putts or fewer"}],"cue":"Pick the line and roll each ball to finish just past the cup.","routine_rule":"Full routine on every putt.","source_url":"https://www.golfdigest.com/story/the-15-best-golf-practice-games"},
  {"category":"short_game","difficulty":"advanced","lower_is_better":false,"status":"active","reps_suggested":9,"equipment_needed":"balls, sand wedge, putter, practice bunker","name":"Bunker Up-and-Down","practice_category":"short_game","description":"Random bunker lies, then hole out.","target_area":"bunkers","time_estimate_mins":20,"instructions":"Drop 9 balls in different bunker lies (flat, uphill, downhill, buried). Play each one out and putt out. Count the up-and-downs (holed in 2 or fewer from the bunker).","locations":["short_game_area"],"equipment":"balls, sand wedge, putter, practice bunker","structure":"random","pressure":1,"metric":"count_of_n","sets":[{"label":"Nine lies","setup":"A different bunker lie for each ball; play out and putt out","balls":9}],"levels":[{"name":"5 of 9","rule":"Get up and down 5 of 9"},{"name":"6 of 9","rule":"Get up and down 6 of 9"}],"cue":"Splash the sand to a landing spot on the green and let the ball release to the cup.","routine_rule":"Full routine on every ball.","source_url":"https://www.golfmagic.com/instruction/bunker-play/luke-donald-mizuno-masterclass-4/10750"},
  {"category":"approach","difficulty":"advanced","lower_is_better":false,"status":"active","reps_suggested":24,"equipment_needed":"wedges, balls, launch monitor or yardage targets","name":"Wedge Matrix","practice_category":"wedges","description":"Three stock lengths per wedge, thrown at random targets.","target_area":"wedge distances","time_estimate_mins":25,"instructions":"For each wedge, hit three stock shot lengths. A partner or the monitor calls a random target inside 100 yards; pick the wedge and length that fits. Count the shots that finish within 10% of the target distance.","locations":["range","home_net","simulator"],"equipment":"wedges, balls, launch monitor or yardage targets","structure":"random","pressure":1,"metric":"count_of_n","sets":[{"label":"Pitching Wedge","setup":"6 random targets; count the shots within the window","balls":6},{"label":"Gap Wedge","setup":"6 random targets; count the shots within the window","balls":6},{"label":"Sand Wedge","setup":"6 random targets; count the shots within the window","balls":6},{"label":"Lob Wedge","setup":"6 random targets; count the shots within the window","balls":6}],"levels":[{"name":"Within 10%","rule":"12 of 24 within 10% of the target distance"},{"name":"Within 7%","rule":"12 of 24 within 7% of the target distance"}],"cue":"Land each ball on the number for that target.","routine_rule":"Full routine on every ball.","source_url":"https://golfpass.com/travel-advisor/articles/rory-mcilroy-golf-instruction-wedge-play-short-game"},
  {"category":"approach","difficulty":"advanced","lower_is_better":false,"status":"active","reps_suggested":18,"equipment_needed":"driver, irons, balls, range targets","name":"Range Nine Holes","practice_category":"approach","description":"Play nine holes on the range: a tee shot to a corridor, then an iron to a green.","target_area":"on-course transfer","time_estimate_mins":30,"instructions":"Pick a corridor and a green-sized target for each of nine holes. Hit a tee shot at the corridor, then an iron at the green. Count the fairways and greens you hit, out of 18.","locations":["range"],"equipment":"driver, irons, balls, range targets","structure":"random","pressure":1,"metric":"count_of_n","sets":[{"label":"Nine holes","setup":"Tee shot to a corridor, then an iron to a green, nine times","balls":18}],"levels":[{"name":"9 of 18","rule":"Hit 9 of 18 fairways and greens"},{"name":"11 of 18","rule":"Hit 11 of 18 fairways and greens"}],"cue":"Pick one target for each shot and send the ball at it.","routine_rule":"Full routine on every ball.","source_url":"https://www.golfdigest.com/story/the-15-best-golf-practice-games"},
  {"category":"approach","difficulty":"advanced","lower_is_better":false,"status":"locked","reps_suggested":9,"equipment_needed":"irons, balls","name":"Nine Windows","practice_category":"approach","description":"Three heights by three shapes, one ball each.","target_area":"ball flight","time_estimate_mins":20,"instructions":"Call one of nine windows (low, mid or high, each with a draw, straight or fade) and hit one ball at it. Count the windows hit out of 9.","locations":["range","home_net","simulator"],"equipment":"irons, balls","structure":"random","pressure":0,"metric":"count_of_n","sets":[{"label":"Nine windows","setup":"One ball for each height and shape","balls":9}],"levels":[{"name":"4 of 9","rule":"Hit 4 of 9 windows"}],"cue":"Start the ball through the window and finish it on the shape you called.","routine_rule":"Full routine on every ball.","source_url":"https://www.golfmagic.com/pga-tour/tiger-woods-shows-taylormade-nine-window-iron-practice-drill"},
  {"category":"putting","difficulty":"intermediate","lower_is_better":true,"status":"active","reps_suggested":3,"equipment_needed":"putter, balls","name":"Three 4-Footers","practice_category":"closeout","description":"Pass-to-leave: three 4-footers in a row, restart on any miss.","target_area":"short putts","time_estimate_mins":5,"instructions":"Put a ball 4 feet from the hole. Make 3 in a row to leave. Any miss restarts the count at zero. Log the total putts it took.","locations":["putting_green"],"equipment":"putter, balls","structure":"blocked","pressure":2,"metric":"strokes","sets":[{"label":"4 ft","setup":"3 makes in a row from 4 ft; a miss restarts the count","balls":3}],"levels":[{"name":"4 ft","rule":"3 in a row from 4 ft"},{"name":"5 ft","rule":"3 in a row from 5 ft"}],"cue":"Roll each putt into the back of the cup.","routine_rule":"Full routine on every putt.","source_url":"https://research.vu.nl/en/publications/training-with-anxiety-has-a-positive-effect-on-expert-perceptual--2/"},
  {"category":"approach","difficulty":"advanced","lower_is_better":false,"status":"active","reps_suggested":39,"equipment_needed":"full bag, balls, range targets","name":"Club Work","practice_category":"approach","description":"A pre-competition block: a few balls with each club at a window of visual targets.","target_area":"carry and dispersion","time_estimate_mins":30,"instructions":"For each club, pick a target and a window on either side of it. Hit 3 balls with a full routine and count the shots that finish inside the window. Log each club's count.","locations":["range","home_net","simulator"],"equipment":"full bag, balls, range targets","structure":"blocked_serial_random","pressure":1,"metric":"count_of_n","sets":[{"label":"Driver","club":"Driver","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"3 Wood","club":"3 Wood","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"7 Wood","club":"7 Wood","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"4 Iron","club":"4 Iron","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"5 Iron","club":"5 Iron","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"6 Iron","club":"6 Iron","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"7 Iron","club":"7 Iron","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"8 Iron","club":"8 Iron","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"9 Iron","club":"9 Iron","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"Pitching Wedge","club":"Pitching Wedge","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"Gap Wedge","club":"Gap Wedge","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"Sand Wedge","club":"Sand Wedge","setup":"Target with a visual window on either side; count the shots inside it","balls":3},{"label":"Lob Wedge","club":"Lob Wedge","setup":"Target with a visual window on either side; count the shots inside it","balls":3}],"levels":[{"name":"Wide window","rule":"2 of 3 inside a 30-yd window with each club"},{"name":"Narrow window","rule":"2 of 3 inside a 20-yd window with each club"}],"cue":"Send each ball through the window around the target.","routine_rule":"Full routine on every ball.","source_url":"https://golf.com/instruction/short-game/tiger-woods-warm-up-practice-routine/"},
  {"category":"off_tee","difficulty":"intermediate","lower_is_better":false,"status":"active","reps_suggested":20,"equipment_needed":"driver, balls, range","name":"Fairway Corridor","practice_category":"tee","description":"Hit drivers into a range \"fairway\" and count how many stay in it.","target_area":"fairways","time_estimate_mins":20,"instructions":"Pick two range targets about 30 yards apart to act as the edges of a fairway. Hit 20 drivers with your full pre-shot routine, one ball at a time. Count how many finish between the two targets.","locations":["range","simulator"],"equipment":"driver, balls, range","structure":"blocked","pressure":0,"metric":"count_of_n","sets":[{"label":"Corridor","setup":"Two targets about 30 yd apart; stock shape only","balls":20}],"levels":[{"name":"30-yd corridor","rule":"12 of 20 inside a 30-yd corridor"},{"name":"24-yd corridor","rule":"12 of 20 inside a 24-yd corridor"}],"cue":"Start the ball at the middle of the corridor and let the stock shape hold it in.","routine_rule":"Full routine on every ball.","source_url":"https://content.schwab.com/web/retail/public/corporatesponsorships/challengers-video-mark-broadie.html"},
  {"category":"approach","difficulty":"advanced","lower_is_better":false,"status":"active","reps_suggested":18,"equipment_needed":"full bag, balls, range","name":"Random Approach Round","practice_category":"approach","description":"Game-like practice: new club and target every ball.","target_area":"on-course transfer","time_estimate_mins":30,"instructions":"Play an imaginary 18 approach shots: every ball gets a new target and yardage, a new club, and your full routine. Pick the aim point before each shot. Count the greens hit.","locations":["range","simulator"],"equipment":"full bag, balls, range","structure":"random","pressure":1,"metric":"count_of_n","sets":[{"label":"Eighteen targets","setup":"A new target, yardage and club for every ball; choose the aim point first","balls":18}],"levels":[{"name":"9 of 18","rule":"Hit 9 of 18 greens"},{"name":"11 of 18","rule":"Hit 11 of 18 greens"}],"cue":"Send the ball at the aim point you picked for that target.","routine_rule":"Full routine on every ball.","source_url":"https://championships.usga.org/content/dam/championships/usndp/images/2025-images/grant-management-center-/Picking-Targets-Into-Greens.pdf"},
  {"category":"short_game","difficulty":"intermediate","lower_is_better":false,"status":"active","reps_suggested":9,"equipment_needed":"balls, wedge, putter, practice green","name":"Up-and-Down Challenge","practice_category":"short_game","description":"Chip and putt out -- it only counts if you save par.","target_area":"scrambling","time_estimate_mins":20,"instructions":"Drop 9 balls at different spots around a green (fringe, rough, uphill, downhill). Play each one: chip, then putt out. Count the up-and-downs (holed in 2 or fewer).","locations":["short_game_area"],"equipment":"balls, wedge, putter, practice green","structure":"random","pressure":1,"metric":"count_of_n","sets":[{"label":"Nine lies","setup":"A different spot and lie for each ball; chip, then putt out","balls":9}],"levels":[{"name":"5 of 9","rule":"Get up and down 5 of 9"},{"name":"6 of 9","rule":"Get up and down 6 of 9"}],"cue":"Pick a landing spot and let the ball release to the cup.","routine_rule":"Full routine on every ball.","source_url":"https://mygolfspy.com/news-opinion/instruction/the-short-game-skills-you-think-you-have-versus-what-the-data-shows/"},
  {"category":"short_game","difficulty":"beginner","lower_is_better":false,"status":"active","reps_suggested":20,"equipment_needed":"balls, wedge, towel, chipping green","name":"Landing Spot Towel","practice_category":"short_game","description":"Pick a landing spot and hit it.","target_area":"chip landing spot","time_estimate_mins":15,"instructions":"Lay a towel on the green about 3 feet on, between you and the hole. Chip 20 balls trying to land each one on the towel. The roll-out takes care of itself once the landing spot is right.","locations":["short_game_area"],"equipment":"balls, wedge, towel, chipping green","structure":"blocked","pressure":0,"metric":"count_of_n","sets":[{"label":"Set 1","setup":"Towel about 3 ft onto the green; count the balls landing within a club-length of it","balls":5},{"label":"Set 2","setup":"Towel about 3 ft onto the green; count the balls landing within a club-length of it","balls":5},{"label":"Set 3","setup":"Towel about 3 ft onto the green; count the balls landing within a club-length of it","balls":5},{"label":"Set 4","setup":"Towel about 3 ft onto the green; count the balls landing within a club-length of it","balls":5}],"levels":[{"name":"Club-length","rule":"12 of 20 land within a club-length of the towel"},{"name":"On the towel","rule":"12 of 20 land on the towel"}],"cue":"Land each ball on the towel and let it roll to the cup.","routine_rule":"Full routine on every ball.","source_url":"https://pubmed.ncbi.nlm.nih.gov/17941543/"}
]
$seed$::jsonb) as s(name text, category text, description text, target_area text, difficulty text, reps_suggested integer, time_estimate_mins integer, instructions text, equipment_needed text, practice_category text, locations text[], equipment text, structure text, pressure smallint, metric text, lower_is_better boolean, sets jsonb, levels jsonb, cue text, routine_rule text, source_url text, status text)
on conflict (name) do update set practice_category = excluded.practice_category, locations = excluded.locations, equipment = excluded.equipment, structure = excluded.structure, pressure = excluded.pressure, metric = excluded.metric, lower_is_better = excluded.lower_is_better, sets = excluded.sets, levels = excluded.levels, cue = excluded.cue, routine_rule = excluded.routine_rule, source_url = excluded.source_url, status = excluded.status;

create index if not exists drill_library_status_idx on public.drill_library (status);

-- Each golfer's current difficulty level per drill (index into drill_library.levels).
create table if not exists public.drill_levels (
  user_id uuid not null references auth.users(id) on delete cascade,
  drill_id uuid not null references public.drill_library(id),
  level smallint not null default 0 check (level >= 0),
  updated_at timestamptz not null default now(),
  unique (user_id, drill_id)
);

alter table public.drill_levels enable row level security;
create policy "select own drill_levels" on public.drill_levels for select using ((select auth.uid()) = user_id);
create policy "insert own drill_levels" on public.drill_levels for insert with check ((select auth.uid()) = user_id);
create policy "update own drill_levels" on public.drill_levels for update using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "delete own drill_levels" on public.drill_levels for delete using ((select auth.uid()) = user_id);
